-- Generated by `ops generate`. One role per audience per environment, holding
-- exactly what the agent's tools touch. DEV has no audience: engineers work as themselves.

{% set audience = {'TEST': 'MKUKREJA', 'PROD': 'MKUKREJA'} %}
{% if env in audience %}

DEFINE ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER
    COMMENT = 'Uses the {{ env }} EBOS_SUPPLY_AGENT agent in CoWork';
GRANT ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER TO USER {{ audience[env] }};

GRANT USAGE ON WAREHOUSE AGENTOPS_CI_WH TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON DATABASE AGENTS_{{ env }} TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON SCHEMA AGENTS_{{ env }}.CORE TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON SCHEMA AGENTS_{{ env }}.CONTEXT TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON SCHEMA AGENTS_{{ env }}.TOOLS TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;

-- The agent's tools
GRANT USAGE ON WAREHOUSE COWORK_EBOS_DEMO_WH TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT SELECT ON SEMANTIC VIEW AGENTS_{{ env }}.CONTEXT.EBOS_SUPPLIER_STOCKOUTS_SV TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON DATABASE EBOS_{{ env }} TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON SCHEMA EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT USAGE ON CORTEX SEARCH SERVICE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.SUPPLIER_NOTICES_SEARCH TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;

-- The data behind the semantic views (their base tables)
GRANT SELECT ON TABLE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.DIM_PRODUCT TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT SELECT ON TABLE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.FACT_PURCHASE_ORDERS TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT SELECT ON TABLE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.FACT_STOCK_POSITIONS TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT SELECT ON TABLE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.DIM_SUPPLIER TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;
GRANT SELECT ON TABLE EBOS_{{ env }}.EBOS_SUPPLIER_STOCKOUTS.DIM_WAREHOUSE TO ROLE EBOS_SUPPLY_AGENT_{{ env }}_USER;

{% endif %}
